<?php
namespace App\Http\Controllers;
use App\Models\Ticket;
use Illuminate\Http\Request;
class ReportController extends Controller { private function query(Request $r){$q=Ticket::with(['school','technician'])->latest();if($r->user()->isDirector())$q->where('unidad_educativa_id',$r->user()->school_id);if($r->filled('from'))$q->whereDate('created_at','>=',$r->from);if($r->filled('to'))$q->whereDate('created_at','<=',$r->to);if($r->filled('category'))$q->where('categoria',Ticket::databaseValue('category',$r->category));if($r->filled('status'))$q->where('estado',Ticket::databaseValue('status',$r->status));return $q;} public function index(Request $r){$rows=$this->query($r)->get();return view('reports.index',['rows'=>$rows,'byStatus'=>$rows->countBy('status'),'byCategory'=>$rows->countBy('category')]);} public function export(Request $r){$rows=$this->query($r)->get();return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fputcsv($out,['Código','Fecha','Unidad educativa','Asunto','Categoría','Prioridad','Estado','Técnico']);foreach($rows as $t)fputcsv($out,[$t->code,$t->created_at->format('Y-m-d H:i'),$t->school->name,$t->subject,$t->category,$t->priority,$t->status,$t->technician?->name]);fclose($out);},'reporte_mantenimiento_'.now()->format('Ymd_His').'.csv',['Content-Type'=>'text/csv; charset=UTF-8']);} }
